def longest_run(cells_set, h, w):
    best=0
    for r in range(h):
        run=0
        for c in range(w):
            run = run+1 if (r,c) in cells_set else 0
            best=max(best,run)
    for c in range(w):
        run=0
        for r in range(h):
            run = run+1 if (r,c) in cells_set else 0
            best=max(best,run)
    # diagonals
    for d in range(-w,h):
        run=0
        for r in range(h):
            c=r-d
            if 0<=c<w and (r,c) in cells_set: run+=1; best=max(best,run)
            else: run=0
    for d in range(h+w):
        run=0
        for r in range(h):
            c=d-r
            if 0<=c<w and (r,c) in cells_set: run+=1; best=max(best,run)
            else: run=0
    return best
def ncomps(cells_set,h,w):
    seen=set(); n=0
    for cell in cells_set:
        if cell in seen: continue
        n+=1; q=deque([cell]); seen.add(cell)
        while q:
            r,c=q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and (nr,nc) in cells_set and (nr,nc) not in seen:
                    seen.add((nr,nc)); q.append((nr,nc))
    return n
def block_feats2(g,i,j):
    cnts=Ctr(v for row in g for v in row)
    top2=set(c for c,_ in cnts.most_common(2))
    bg=cnts.most_common(1)[0][0]; bg2=[c for c,_ in cnts.most_common(2)][1]
    B=[row[j*3:j*3+3] for row in g[i*3:i*3+3]]
    h=len(B); w=len(B[0])
    f={}
    f['i'],f['j']=i,j
    f['bg2']=bg2
    for c in set(v for row in g for v in row):
        f[f'n{c}']=sum(1 for r in range(h) for c2 in range(w) if B[r][c2]==c)
    f['wall']=sum(1 for r in range(h) for c2 in range(w) if B[r][c2] not in top2)
    wallcells={(r,c) for r in range(h) for c in range(w) if B[r][c] not in top2}
    f['wallcomps']=ncomps(wallcells,h,w)
    f['wallrun']=longest_run(wallcells,h,w)
    zerocells={(r,c) for r in range(h) for c in range(w) if B[r][c]==bg}
    f['zerocomps']=ncomps(zerocells,h,w)
    f['zerorun']=longest_run(zerocells,h,w)
    f['area']=h*w
    f['nb']=f['wall']
    return f
